const greeter = {
  hello() {
    return `hello from ${this.name}`;
  },
};

class Guest {
  constructor(name) {
    this.name = name;
  }

  hello() {
    return "class hello";
  }
}

Object.assign(Guest.prototype, greeter);

const guest = new Guest("Ada");

console.log(guest.hello());
console.log(Object.hasOwn(guest, "hello"));
console.log(Guest.prototype.hello === greeter.hello);
